<template>
  <div class="workspace-page"><header class="workspace-header"><div><span class="eyebrow">Execution</span><h1>Today's Tasks</h1><p>كل ما تحتاج تنفذه اليوم في مكان واحد.</p></div><button class="primary-btn" @click="openCreate">＋ مهمة جديدة</button></header>
    <div v-if="error" class="alert error">{{ error }}</div><div v-if="success" class="alert success">{{ success }}</div>
    <section class="task-layout"><div class="content-card"><div class="task-toolbar"><strong>{{ tasks.length }} مهام اليوم</strong><select v-model="filter"><option value="all">الكل</option><option value="pending">Pending</option><option value="in_progress">In Progress</option><option value="completed">Completed</option><option value="postponed">Postponed</option></select></div><div v-if="loading" class="loading">جاري التحميل...</div><div v-else-if="tasks.length===0" class="empty">مفيش مهام لليوم. ممتاز! أو أنشئ مهمة جديدة.</div><div v-else class="task-list"><article v-for="task in visibleTasks" :key="task.id" class="task-row" :class="task.status"><button class="check" :disabled="task.status==='completed'" @click="finish(task)">{{ task.status==='completed'?'✓':'○' }}</button><div class="task-body"><div class="task-title"><h3>{{ task.title }}</h3><span class="pill">{{ task.priority_display || task.priority }}</span></div><p>{{ task.description || 'بدون وصف' }}</p><div class="task-meta"><span v-if="task.scheduled_start">🕒 {{ task.scheduled_start }}</span><span>⏱ {{ task.estimated_minutes || 0 }}m</span><span v-if="task.overdue" class="overdue">متأخرة</span></div></div><div class="task-actions"><button v-if="task.status!=='completed'" @click="openPostpone(task)">تأجيل</button><button @click="editTask(task)">تعديل</button><button class="danger" @click="removeTask(task)">حذف</button></div></article></div></div><aside class="content-card summary"><h2>ملخص اليوم</h2><div class="ring"><strong>{{ completion }}%</strong><span>إنجاز</span></div><div class="summary-line"><span>Completed</span><strong>{{ completed }}</strong></div><div class="summary-line"><span>Remaining</span><strong>{{ Math.max(tasks.length-completed,0) }}</strong></div><div class="summary-line"><span>Estimated</span><strong>{{ estimated }}m</strong></div></aside></section>
    <div v-if="dialog" class="modal-backdrop" @click.self="dialog=false"><form class="modal-card" @submit.prevent="save"><div class="modal-head"><h2>{{ editing?'تعديل المهمة':'مهمة جديدة' }}</h2><button type="button" @click="dialog=false">×</button></div><label>العنوان<input v-model.trim="form.title" required /></label><label>الوصف<textarea v-model="form.description" rows="3"></textarea></label><div class="form-grid"><label>التاريخ<input v-model="form.scheduled_date" type="date" required /></label><label>وقت البداية<input v-model="form.scheduled_start" type="time" /></label><label>الأولوية<select v-model="form.priority"><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="critical">Critical</option></select></label><label>الحالة<select v-model="form.status"><option value="pending">Pending</option><option value="in_progress">In Progress</option><option value="postponed">Postponed</option><option value="cancelled">Cancelled</option></select></label><label>المدة المتوقعة<input v-model.number="form.estimated_minutes" type="number" min="0" /></label></div><div class="modal-actions"><button type="button" @click="dialog=false">إلغاء</button><button class="primary-btn">حفظ</button></div></form></div>
    <div v-if="postponeDialog" class="modal-backdrop" @click.self="postponeDialog=false"><form class="modal-card small" @submit.prevent="postpone"><h2>تأجيل المهمة</h2><label>اليوم الجديد<input v-model="postponeDate" type="date" required /></label><div class="modal-actions"><button type="button" @click="postponeDialog=false">إلغاء</button><button class="primary-btn">تأجيل</button></div></form></div>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { completeTask, createTask, deleteTask, listTodayTasks, postponeTask, updateTask } from '@/services/tasks'
const tasks=ref([]),loading=ref(false),dialog=ref(false),postponeDialog=ref(false),editing=ref(null),postponing=ref(null),filter=ref('all'),error=ref(''),success=ref(''),postponeDate=ref('')
const form=reactive({title:'',description:'',scheduled_date:new Date().toISOString().slice(0,10),scheduled_start:'',priority:'medium',status:'pending',estimated_minutes:0})
const completed=computed(()=>tasks.value.filter(t=>t.status==='completed').length), completion=computed(()=>tasks.value.length?Math.round(completed.value/tasks.value.length*100):0), estimated=computed(()=>tasks.value.reduce((a,t)=>a+Number(t.estimated_minutes||0),0)), visibleTasks=computed(()=>filter.value==='all'?tasks.value:tasks.value.filter(t=>t.status===filter.value))
const load=async()=>{loading.value=true;try{tasks.value=await listTodayTasks()}catch(e){error.value=e.response?.data?.detail||'تعذر تحميل المهام.'}finally{loading.value=false}}
const reset=()=>Object.assign(form,{title:'',description:'',scheduled_date:new Date().toISOString().slice(0,10),scheduled_start:'',priority:'medium',status:'pending',estimated_minutes:0})
const openCreate=()=>{editing.value=null;reset();dialog.value=true}
const editTask=t=>{editing.value=t.id;Object.assign(form,{title:t.title,description:t.description,scheduled_date:t.scheduled_date,scheduled_start:t.scheduled_start||'',priority:t.priority,status:t.status,estimated_minutes:t.estimated_minutes||0});dialog.value=true}
const save=async()=>{try{const payload={...form,scheduled_start:form.scheduled_start||null};editing.value?await updateTask(editing.value,payload):await createTask(payload);dialog.value=false;success.value='تم حفظ المهمة.';await load()}catch(e){error.value=e.response?.data?.detail||'تعذر حفظ المهمة.'}}
const finish=async t=>{try{await completeTask(t.id,t.actual_minutes||t.estimated_minutes||0);success.value='تم إكمال المهمة.';await load()}catch(e){error.value=e.response?.data?.detail||'تعذر إكمال المهمة.'}}
const openPostpone=t=>{postponing.value=t.id;postponeDate.value=new Date(Date.now()+86400000).toISOString().slice(0,10);postponeDialog.value=true}
const postpone=async()=>{try{await postponeTask(postponing.value,postponeDate.value);postponeDialog.value=false;success.value='تم تأجيل المهمة.';await load()}catch(e){error.value=e.response?.data?.detail||'تعذر تأجيل المهمة.'}}
const removeTask=async t=>{if(!window.confirm(`حذف المهمة "${t.title}"؟`))return;try{await deleteTask(t.id);await load()}catch(e){error.value=e.response?.data?.detail||'تعذر حذف المهمة.'}}
onMounted(load)
</script>
<style scoped>
.workspace-page{min-height:100vh;padding:32px;max-width:1400px;margin:auto;color:#e5e7eb}.workspace-header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;margin-bottom:24px}.eyebrow{color:#60a5fa;font-size:12px;text-transform:uppercase;letter-spacing:.12em}.workspace-header h1{margin:6px 0;font-size:34px}.workspace-header p{margin:0;color:#94a3b8}.primary-btn{background:#2563eb;color:white;border:0;border-radius:10px;padding:11px 16px;font-weight:700}.task-layout{display:grid;grid-template-columns:1fr 300px;gap:16px}.content-card{background:#111827;border:1px solid #253044;border-radius:16px;padding:18px}.task-toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.task-toolbar select{background:#0f172a;color:#e5e7eb;border:1px solid #334155;border-radius:8px;padding:8px}.task-row{display:flex;align-items:flex-start;gap:14px;padding:16px 0;border-bottom:1px solid #1f2937}.task-row:last-child{border-bottom:0}.check{width:30px;height:30px;border-radius:50%;border:1px solid #475569;background:#0f172a;color:#60a5fa;font-size:18px}.task-body{flex:1}.task-title{display:flex;gap:10px;align-items:center}.task-title h3{margin:0}.task-body p{color:#94a3b8;margin:5px 0}.task-meta{display:flex;gap:12px;color:#64748b;font-size:12px}.overdue{color:#fca5a5}.pill{padding:3px 7px;border-radius:999px;background:#334155;font-size:10px}.task-actions{display:flex;gap:5px}.task-actions button{background:#1f2937;color:#cbd5e1;border:0;border-radius:7px;padding:7px}.danger{color:#fca5a5!important}.summary h2{margin-top:0}.ring{width:130px;height:130px;border-radius:50%;border:12px solid #1e3a8a;margin:20px auto;display:grid;place-items:center;align-content:center}.ring strong{font-size:26px}.ring span{font-size:11px;color:#94a3b8}.summary-line{display:flex;justify-content:space-between;padding:12px 0;border-top:1px solid #1f2937;color:#94a3b8}.alert{padding:12px;border-radius:10px;margin-bottom:14px}.alert.error{background:#451a1a;color:#fecaca}.alert.success{background:#052e1b;color:#bbf7d0}.loading,.empty{text-align:center;padding:40px;color:#94a3b8}.modal-backdrop{position:fixed;inset:0;background:#0009;display:grid;place-items:center;padding:20px;z-index:100}.modal-card{width:min(680px,100%);background:#111827;border:1px solid #334155;border-radius:16px;padding:20px}.modal-card.small{width:400px}.modal-head,.modal-actions{display:flex;justify-content:space-between;align-items:center}.modal-head button{background:none;border:0;color:#94a3b8;font-size:24px}.modal-card label{display:block;margin-top:14px;font-size:13px;color:#cbd5e1}.modal-card input,.modal-card textarea,.modal-card select{width:100%;margin-top:6px;background:#0f172a;color:#e5e7eb;border:1px solid #334155;border-radius:9px;padding:10px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.modal-actions{justify-content:flex-end;gap:10px;margin-top:20px}.modal-actions button:not(.primary-btn){background:#1f2937;color:#e5e7eb;border:0;border-radius:8px;padding:9px 12px}@media(max-width:900px){.task-layout{grid-template-columns:1fr}.workspace-page{padding:18px}.workspace-header{flex-direction:column}.form-grid{grid-template-columns:1fr}.task-actions{flex-direction:column}}
</style>
